// Código do nó "Montar mensagem" (n8n Code node, modo "Run Once for All Items")
const DESTINO = '5518981034411'; // WhatsApp comercial que recebe o aviso

const b = $input.first().json.body || {};
const v = (x) => String(x ?? '').trim();
const linha = (rotulo, valor) => `*${rotulo}:* ${v(valor) || '—'}`;

const digitos = v(b.phone).replace(/\D/g, '');
let waLead = '';
if (digitos.length >= 10) {
  const numero = digitos.length <= 11 ? '55' + digitos.replace(/^0+/, '') : digitos;
  waLead = `https://wa.me/${numero}`;
}

const utm = b.utm || {};
const origem = [utm.utm_source, utm.utm_medium, utm.utm_campaign].filter(Boolean).join(' / ');
const extrasOrigem = [utm.utm_content && `anúncio: ${utm.utm_content}`, utm.fbclid && 'fbclid', utm.gclid && 'gclid'].filter(Boolean).join(' · ');

const quando = new Date(b.submittedAt || Date.now()).toLocaleString('pt-BR', { timeZone: 'America/Sao_Paulo', dateStyle: 'short', timeStyle: 'short' });

const partes = [
  '🟢 *Novo lead — site TA Consulting*',
  '',
  linha('Nome', b.name),
  linha('Empresa', b.company),
  linha('E-mail', b.email),
  linha('WhatsApp', b.phone),
  '',
  '*Como podemos ajudar?*',
  v(b.challenge) || '—',
  '',
  linha('Origem', origem || 'direto / orgânico'),
];
if (extrasOrigem) partes.push(`_${extrasOrigem}_`);
partes.push(linha('Página', b.page), linha('Recebido em', quando));
if (waLead) partes.push('', `👉 Responder: ${waLead}`);

return [{ json: { number: DESTINO, text: partes.join('\n') } }];
